package app.metrolife;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.IOException;
import java.util.*;

/** Shared footprint collision and server-time speed budget, independent of render rate. */
final class Navigation {
 final GameService g;final JsonNode data;JsonNode interiors,venues;
 final Map<String,Long> times=new HashMap<>();final Map<String,Double> credits=new HashMap<>();
 Navigation(GameService g){this.g=g;try(var in=getClass().getResourceAsStream("/static-data/navigation.json")){data=g.mapper.readTree(in);try(var rooms=getClass().getResourceAsStream("/static-data/interiors.json")){interiors=g.mapper.readTree(rooms);try(var v=getClass().getResourceAsStream("/static-data/venues.json")){venues=g.mapper.readTree(v);}}}catch(IOException e){throw new IllegalStateException("Navigation data missing",e);}}
 JsonNode city(String city){return data.path("cities").path(city);}
 JsonNode door(ObjectNode s,String place){return place.equals("home")?city(s.path("city").asText()).path("homes").path(s.path("home").path("neighborhood").asText()):city(s.path("city").asText()).path("doors").path(place);}
 ObjectNode position(ObjectNode s){String place=s.path("loc").asText();if(!s.path("position").isObject()||!s.path("position").path("place").asText().equals(place)||!s.path("position").path("city").asText().equals(s.path("city").asText())){JsonNode d=door(s,place);ObjectNode p=s.putObject("position").put("x",d.path("x").asDouble()).put("z",d.path("z").asDouble()).put("face",Math.PI).put("place",place).put("city",s.path("city").asText()).putNull("room");String key=s.path("worldId").asText()+s.path("userId").asText();times.put(key,g.now());credits.put(key,2.4);return p;}return (ObjectNode)s.path("position");}
 static boolean polygon(double x,double z,JsonNode poly){boolean inside=false;for(int i=0,j=poly.size()-1;i<poly.size();j=i++){JsonNode a=poly.get(i),b=poly.get(j);double ax=a.get(0).asDouble(),az=a.get(1).asDouble(),bx=b.get(0).asDouble(),bz=b.get(1).asDouble();if((az>z)!=(bz>z)&&x<(bx-ax)*(z-az)/(bz-az)+ax)inside=!inside;}return inside;}
 static boolean box(double x,double z,JsonNode b,double pad){double dx=x-b.path("x").asDouble(),dz=z-b.path("z").asDouble(),a=b.path("a").asDouble(),c=Math.cos(a),s=Math.sin(a);return Math.abs(dx*c-dz*s)<b.path("w").asDouble()/2+pad&&Math.abs(dx*s+dz*c)<b.path("d").asDouble()/2+pad;}
 boolean stand(String city,double x,double z,String room){if(!room.isEmpty()){JsonNode layout=interiors.path(room.split(":")[0]);if(!layout.isObject()||Math.abs(x)>=(room.startsWith("home:")?3.25:5.5)||Math.abs(z)>=(room.startsWith("home:")?2.75:4.5))return false;for(JsonNode b:layout.path("boxes"))if(box(x,z,b,.3))return false;return true;}JsonNode n=city(city);boolean land=false;for(JsonNode p:n.path("land"))if(polygon(x,z,p))land=true;for(JsonNode b:n.path("bridges"))if(box(x,z,b,-.35))land=true;if(!land)return false;for(JsonNode p:n.path("water"))if(polygon(x,z,p))return false;for(JsonNode b:n.path("boxes"))if(box(x,z,b,.3))return false;return true;}
 String type(String city,String loc){if(loc.equals("home"))return "home";for(String type:List.of("cafe","club"))if(venues.path(city).path(type).asText().equals(loc))return type;for(String track:Content.TRACKS)if(Content.workplace(city,track).equals(loc))return "work";return "";}
 String roomId(ObjectNode s,String loc){String type=type(s.path("city").asText(),loc);return type+":"+(loc.equals("home")?s.path("userId").asText():loc);}
 void idle(ObjectNode s){GameService.require(s.path("busyUntil").isNull()&&s.path("pendingBeat").isNull(),409,"Finish this moment first");}
 void atDoor(ObjectNode s,String loc){ObjectNode p=position(s);JsonNode d=door(s,loc);GameService.require(d.isObject()&&p.path("room").isNull()&&Math.hypot(d.path("x").asDouble()-p.path("x").asDouble(),d.path("z").asDouble()-p.path("z").asDouble())<=3,409,"Walk to the door first");}
 void atStation(ObjectNode s,String loc,String station){ObjectNode p=position(s);GameService.require(p.path("room").asText().equals(roomId(s,loc)),409,"Walk inside first");JsonNode chosen=null;for(JsonNode row:interiors.path(type(s.path("city").asText(),loc)).path("stations"))if(row.path("id").asText().equals(station))chosen=row;GameService.require(chosen!=null&&Math.hypot(p.path("x").asDouble()-chosen.path("x").asDouble(),p.path("z").asDouble()-chosen.path("z").asDouble())<=1.45,409,"Walk up to the furniture first");p.put("face",chosen.path("face").asDouble());}
 ObjectNode door(String token,JsonNode body){
  ObjectNode ses=g.session(token,true),s=g.sim(ses),w=g.world(ses);g.decay(s,w);ObjectNode p=position(s);idle(s);boolean enter=body.path("enter").asBoolean();
  if(enter){String loc=body.path("loc").asText(),city=s.path("city").asText(),type=type(city,loc);GameService.require(!type.isEmpty(),400,"This building has no room to enter");if(loc.equals("home"))GameService.require(s.path("home").path("city").asText().equals(city),403,"Your home is in another city");else if(!type.equals("club"))GameService.require(g.civic.open(w,city,g.content.landmark(city,loc),g.clock(w).path("hour").asInt()),409,"This place is closed");atDoor(s,loc);s.set("_outside",p.deepCopy());s.put("loc",loc);p.put("place",loc).put("room",roomId(s,loc)).put("x",interiors.path(type).path("exit").path("x").asDouble()).put("z",interiors.path(type).path("exit").path("z").asDouble()).put("face",Math.PI);
  }else{GameService.require(!p.path("room").isNull(),409,"You are already outside");JsonNode exit=interiors.path(p.path("room").asText().split(":")[0]).path("exit");GameService.require(Math.hypot(p.path("x").asDouble()-exit.path("x").asDouble(),p.path("z").asDouble()-exit.path("z").asDouble())<=1.5,409,"Walk to the exit first");JsonNode outside=s.remove("_outside");if(outside!=null){s.set("position",outside);s.put("loc",outside.path("place").asText());}else{s.remove("position");position(s);}s.withObject("position").putNull("room");if(p.path("room").asText().startsWith("home:"))g.firstDay.mark(s,"outside");}
  g.store.save();return g.simResponse(s,w);
 }
 void requireAction(ObjectNode s,String loc,String action){
  String type=type(s.path("city").asText(),loc);if(type.isEmpty()){atDoor(s,loc);return;}if(type.equals("home")){for(JsonNode row:interiors.path(type).path("stations"))if(row.path("action").asText().equals(action)){atStation(s,loc,row.path("id").asText());return;}throw new ApiException(409,"Walk up to the furniture first");}
  JsonNode a=null;for(JsonNode row:g.content.landmark(s.path("city").asText(),loc).path("actions"))if(row.path("id").asText().equals(action))a=row;
  if(type.equals("work")||a!=null&&a.path("requires").has("job")){atStation(s,loc,"desk");return;}
  List<String> allowed=type.equals("cafe")?List.of("counter","table"):a!=null&&a.path("kind").asText().equals("work")?List.of("stage"):List.of("dance","stage");
  ObjectNode p=position(s);for(JsonNode row:interiors.path(type).path("stations"))if(allowed.contains(row.path("id").asText())&&Math.hypot(p.path("x").asDouble()-row.path("x").asDouble(),p.path("z").asDouble()-row.path("z").asDouble())<=1.45){atStation(s,loc,row.path("id").asText());return;}throw new ApiException(409,"Walk up to the furniture first");
 }
 ObjectNode travel(String token,JsonNode body){ObjectNode ses=g.session(token,true),s=g.sim(ses),w=g.world(ses);g.decay(s,w);idle(s);GameService.require(position(s).path("room").isNull(),409,"Leave the room before map travel");String city=body.path("city").asText(),loc=body.path("loc").asText();GameService.require(city.equals(s.path("city").asText()),403,"Use the airport to fly to another city");if(loc.equals("home"))GameService.require(s.path("home").path("city").asText().equals(city),403,"Your home is in another city");else g.content.landmark(city,loc);JsonNode d=door(s,loc);GameService.require(d.isObject(),404,"Choose a doorway");s.put("busyStartedAt",g.now()).put("busyUntil",g.now()+2000).put("busyLabel","Heading to "+d.path("name").asText());s.put("_pendingTravel",loc);g.store.save();return g.simResponse(s,w);}
 void settleTravel(ObjectNode s){JsonNode loc=s.remove("_pendingTravel");if(loc!=null){s.put("loc",loc.asText());s.remove("position");position(s);}}
 ObjectNode move(String token,JsonNode b){ObjectNode ses=g.session(token,true),s=g.sim(ses),w=g.world(ses);g.decay(s,w);ObjectNode p=position(s);GameService.require(s.path("busyUntil").isNull()&&s.path("pendingBeat").isNull(),409,"Finish this moment before walking");GameService.require(b.path("city").asText().equals(s.path("city").asText()),409,"You are in a different city");double x=b.path("x").asDouble(Double.NaN),z=b.path("z").asDouble(Double.NaN),face=b.path("face").asDouble(Double.NaN);GameService.require(Double.isFinite(x)&&Double.isFinite(z)&&Double.isFinite(face),400,"Send a finite position");String key=s.path("worldId").asText()+s.path("userId").asText();long at=g.now();double budget=Math.min(3,credits.getOrDefault(key,1.5d)+Math.max(0,at-times.getOrDefault(key,at))*.0075),distance=Math.hypot(x-p.path("x").asDouble(),z-p.path("z").asDouble());times.put(key,at);credits.put(key,budget);GameService.require(distance<=budget+1e-6,409,"That is faster than running");int steps=Math.max(1,(int)Math.ceil(distance/.15));for(int i=1;i<=steps;i++){double t=(double)i/steps;GameService.require(stand(s.path("city").asText(),p.path("x").asDouble()+(x-p.path("x").asDouble())*t,p.path("z").asDouble()+(z-p.path("z").asDouble())*t,p.path("room").asText("")),409,"The path is blocked");}credits.put(key,budget-distance);p.put("x",x).put("z",z).put("face",face);if(p.path("room").isNull()){String near="street";double best=3;Iterator<String> ids=city(s.path("city").asText()).path("doors").fieldNames();while(ids.hasNext()){String id=ids.next();JsonNode d=door(s,id);double d2=Math.hypot(d.path("x").asDouble()-x,d.path("z").asDouble()-z);if(d2<best){best=d2;near=id;}}if(s.path("home").path("city").equals(s.path("city"))){JsonNode d=door(s,"home");if(Math.hypot(d.path("x").asDouble()-x,d.path("z").asDouble()-z)<best)near="home";}s.put("loc",near);p.put("place",near);}g.community.online.put(s.path("worldId").asText()+":"+s.path("userId").asText(),at);ObjectNode out=g.object();out.set("position",p.deepCopy());out.put("now",at);return out;}
}
